import {
  installGlobalErrorHandlers,
  reportGlobalError,
} from './shared/services/globalError.ts';

installGlobalErrorHandlers();

// 原生 App 注入支持：从 window.__GKD_SNAPSHOT__ 读取快照
const initNativeSnapshot = async () => {
  const w = window as any;
  if (w.__GKD_SNAPSHOT__) {
    try {
      const { setSnapshot } = await import('@/entities/snapshot/storage');
      const snapshot = typeof w.__GKD_SNAPSHOT__ === 'string'
        ? JSON.parse(w.__GKD_SNAPSHOT__)
        : w.__GKD_SNAPSHOT__;
      let bf = new ArrayBuffer(0);
      if (w.__GKD_SCREENSHOT__) {
        const binary = atob(w.__GKD_SCREENSHOT__);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) {
          bytes[i] = binary.charCodeAt(i);
        }
        bf = bytes.buffer;
      }
      await setSnapshot(snapshot, bf);
      console.log('[GKD] 原生快照已加载');
    } catch (e) {
      console.error('[GKD] 原生快照加载失败', e);
    }
  }
};

void import('./app/bootstrap.ts').then(() => {
  // App 启动后尝试加载原生注入的快照
  setTimeout(initNativeSnapshot, 500);
}).catch((error: unknown) => {
  reportGlobalError(error, '应用启动');
});
